/**
 * Cloudinary image storage driver (production default).
 * - Images are stored as Cloudinary assets — never on the app server, never in Mongo.
 * - Unique public IDs are generated by Cloudinary inside the "nilaara/products" folder.
 * - Incoming transformation strips EXIF/metadata; delivery applies auto format + quality.
 */
const env = require("../../config/env");
const crypto = require("crypto");

const FOLDER = "nilaara/products";

let cloudinary;
function client() {
  if (!cloudinary) {
    cloudinary = require("cloudinary").v2;
    cloudinary.config({
      cloud_name: env.CLOUDINARY_CLOUD_NAME,
      api_key: env.CLOUDINARY_API_KEY,
      api_secret: env.CLOUDINARY_API_SECRET,
      secure: true,
    });
  }
  return cloudinary;
}

function saveImage({ buffer, format }) {
  const c = client();
  // Explicit unique public id so deletion/reference logic is always unambiguous.
  const publicId = `nil-${Date.now().toString(36)}-${crypto.randomBytes(6).toString("hex")}`;
  return new Promise((resolve, reject) => {
    const stream = c.uploader.upload_stream(
      {
        folder: FOLDER,
        public_id: publicId,
        unique_filename: false,
        overwrite: false,
        resource_type: "image",
        format, // normalise extension (jpg/png/webp/gif)
        transformation: [{ fetch_format: "auto", quality: "auto" }],
      },
      (err, res) => {
        if (err) return reject(err);
        resolve({
          url: res.secure_url,
          publicId: res.public_id, // e.g. nilaara/products/nil-…
          bytes: res.bytes,
          format: res.format,
          width: res.width,
          height: res.height,
          provider: "cloudinary",
        });
      }
    );
    stream.end(buffer);
  });
}

async function deleteImage(publicId) {
  try {
    await client().uploader.destroy(publicId, { resource_type: "image", invalidate: true });
    return true;
  } catch (e) {
    console.error("[storage] cloudinary delete failed:", e.message);
    return false;
  }
}

/** Used by the migration script to re-host external images (e.g. legacy Unsplash URLs). */
function saveRemote({ remoteUrl, format }) {
  const c = client();
  return c.uploader.upload(remoteUrl, {
    folder: FOLDER,
    unique_filename: true,
    overwrite: false,
    resource_type: "image",
    ...(format ? { format } : {}),
    transformation: [{ fetch_format: "auto", quality: "auto" }],
  });
}

module.exports = { saveImage, deleteImage, saveRemote, FOLDER };
